glScissor:
static void th_glScissor(CPU *c)
{
    gl_trace("glScissor");
    int x = (int)(GLint)A32(0);
    int y = (int)(GLint)A32(1);
    int w = (int)(GLsizei)A32(2);
    int h = (int)(GLsizei)A32(3);
    host_viewport_scale(&x, &y, &w, &h);
    glScissor(x, y, w, h);
    gl_check("glScissor");
}

