glTexParameterf:
static void th_glTexParameterf(CPU *c)
{
    gl_trace("glTexParameterf");
    GLenum target = (GLenum)A32(0);
    GLenum pname = (GLenum)A32(1);
    glTexParameterf(target, pname, gl_arg_f(c, 2));
    if (pname == GL_TEXTURE_MIN_FILTER) apply_anisotropy(target);
    gl_check("glTexParameterf");
}

