glGetIntegerv:
static void th_glGetIntegerv(CPU *c)
{
    gl_trace("glGetIntegerv");
    GLenum pname=(GLenum)A32(0);
    GLint *out=(GLint *)GP(A32(1));
    glGetIntegerv(pname,out);
#if defined(_WIN64) && !defined(LINDBERGH_OPENXR) && !defined(LINDBERGH_VULKAN)
    /* The arcade must read back cabinet units, not the scaled desktop viewport. */
    int width,height;lindbergh_window_size(&width,&height);
    if(height>0 && width*3==height*4 && (pname==GL_VIEWPORT || pname==GL_SCISSOR_BOX)){
        host_viewport_unscale(out);
    }
#endif
    gl_check("glGetIntegerv");
}

glGetFloatv:
static void th_glGetFloatv(CPU *c)
{
    gl_trace("glGetFloatv");
    GLenum pname=(GLenum)A32(0);
    GLfloat *out=(GLfloat *)GP(A32(1));
    glGetFloatv(pname,out);
#if defined(_WIN64) && !defined(LINDBERGH_OPENXR) && !defined(LINDBERGH_VULKAN)
    /* The arcade must read back cabinet units, not the scaled desktop viewport. */
    int width,height;lindbergh_window_size(&width,&height);
    if(height>0 && width*3==height*4 && (pname==GL_VIEWPORT || pname==GL_SCISSOR_BOX)){
        int rect[4];for(int i=0;i<4;i++)rect[i]=(int)out[i];
        host_viewport_unscale(rect);for(int i=0;i<4;i++)out[i]=(GLfloat)rect[i];
    }
#endif
    gl_check("glGetFloatv");
}
